from hypothesis import given
import hypothesis.strategies as st
from solution import is_palindrome


def reference(text: str) -> bool:
    return text == text[::-1]


def test_examples_given_in_spec():
    assert is_palindrome('') is True
    assert is_palindrome('aba') is True
    assert is_palindrome('aaaaa') is True
    assert is_palindrome('zbcd') is False


def test_empty_string_is_palindrome():
    assert is_palindrome('') is True


def test_single_character_always_palindrome():
    assert is_palindrome('a') is True
    assert is_palindrome('Z') is True
    assert is_palindrome(' ') is True


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=122), min_size=1, max_size=1))
def test_single_character_property(ch):
    assert is_palindrome(ch) is True


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=20))
def test_equivalence_to_reverse_reference_model(text):
    assert is_palindrome(text) is reference(text)


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=20))
def test_reverse_symmetry_metamorphic(text):
    assert is_palindrome(text) == is_palindrome(text[::-1])


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=10))
def test_even_mirror_construction_is_palindrome(s):
    constructed = s + s[::-1]
    assert is_palindrome(constructed) is True


@given(
    st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=10),
    st.characters(min_codepoint=97, max_codepoint=99),
)
def test_odd_mirror_construction_is_palindrome(s, c):
    constructed = s + c + s[::-1]
    assert is_palindrome(constructed) is True


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=10))
def test_repeated_mirror_still_palindrome(s):
    p = s + s[::-1]
    for k in [0, 1, 2, 3, 5]:
        assert is_palindrome(p * k) is True


@given(
    st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=8),
    st.characters(min_codepoint=97, max_codepoint=99),
)
def test_wrapping_mirror_with_same_char_preserves_palindrome(s, c):
    p = s + s[::-1]
    wrapped = c + p + c
    assert is_palindrome(wrapped) is True


@given(
    st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=8),
    st.sampled_from(['a', 'b', 'c']),
    st.sampled_from(['a', 'b', 'c']),
)
def test_mismatched_center_breaks_palindrome(s, a, b):
    if a == b:
        return
    constructed = s + a + b + s[::-1]
    assert is_palindrome(constructed) is False


def test_double_same_char_is_palindrome():
    assert is_palindrome('aa') is True
    assert is_palindrome('zz') is True


def test_double_different_chars_not_palindrome():
    assert is_palindrome('ab') is False
    assert is_palindrome('zb') is False
    assert is_palindrome('ba') is False


@given(
    st.sampled_from(['a', 'b', 'c']),
    st.sampled_from(['a', 'b', 'c']),
)
def test_length_two_characterizes_equality(a, b):
    assert is_palindrome(a + b) is (a == b)


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=20))
def test_palindrome_implies_first_equals_last(text):
    if len(text) >= 1 and is_palindrome(text):
        assert text[0] == text[-1]


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=2, max_size=20))
def test_first_not_equal_last_implies_not_palindrome(text):
    if text[0] != text[-1]:
        assert is_palindrome(text) is False


@given(st.text(alphabet=st.characters(min_codepoint=97, max_codepoint=99), min_size=0, max_size=10))
def test_appending_different_char_to_palindrome_core_breaks_it(s):
    # s + 'ab' with distinct trailing pair cannot be palindrome
    # when built as x + a + b + reverse(x) with a != b
    t = s + "a" + "b" + s[::-1]
    assert t != t[::-1]
    assert is_palindrome(t) is False


def test_case_sensitive_exact_match():
    assert is_palindrome('AbA') is True
    assert is_palindrome('Aba') is False
    assert is_palindrome('ABA') is True
    assert is_palindrome('ABa') is False


def test_returns_bool():
    assert is_palindrome('aba') in (True, False)
    assert type(is_palindrome('aba')) is bool
    assert type(is_palindrome('zbcd')) is bool
    assert type(is_palindrome('')) is bool
